INSERT INTO site_content (contentKey, title, content, sortOrder) VALUES ('footer_brand_desc', '底部品牌简介', '安徽宁商科技集团有限公司，立足安徽本土，聚焦科创产业服务，秉持"务实笃行、创新赋能、诚信致远"的核心价值观。', 70);

UPDATE news SET
    title = '安徽宁商科技集团成立',
    category = 'group',
    category_name = '集团新闻',
    date = '2026-07',
    author = '宁商科技集团品牌策划部',
    source = '内部资料',
    summary = '7月28日，安徽宁商科技集团在合肥市包河区正式成立。作为扎根安徽本土、聚焦科创产业服务的综合性科技企业，集团深度融入合肥科技创新发展布局。',
    body = '<p>7月28日，安徽宁商科技集团在合肥市包河区正式成立。作为扎根安徽本土、聚焦科创产业服务的综合性科技企业，集团深度融入合肥科技创新发展布局，为区域产业升级与科创生态建设注入本土企业新动能。</p><p>合肥作为全国知名的科创名城，创新资源集聚、产业氛围浓厚。宁商科技集团扎根巢湖之畔，承袭徽商务实重信的精神底色，依托合肥科创产业资源与巢湖生态经济带区位优势，确立"科技赋能产业、服务贯穿全程"的核心发展路径，紧扣安徽高质量发展方向，推动本土文化底蕴与科创发展机遇有机融合，稳步构建多元化科创产业服务体系。</p><p>集团始终秉持企业与员工共同成长的发展理念，视人才为科技创新的核心支撑。在深耕科创主业的同时，着力搭建完善的人才成长平台，畅通职业发展通道，营造鼓励创新、实干担当的团队氛围，让员工在企业发展进程中提升专业能力、实现个人价值；员工的成长与活力也反向赋能企业的持续发展，形成双向奔赴、共生共长的良性循环。</p><p>下一步，安徽宁商科技集团将以此次成立为新起点，深耕合肥本土科创土壤，持续提升科创服务能力，携手全体员工共成长、共奋进，为区域科创产业高质量发展贡献力量。</p>'
WHERE id = 1;

UPDATE news SET
    title = '安徽宁商科技集团官方网站正式上线',
    category = 'group',
    category_name = '集团新闻',
    date = '2026-08',
    author = '宁商科技集团品牌策划部',
    source = '内部资料',
    summary = '近日，安徽宁商科技集团官方网站正式开通运行。作为集团对外品牌展示与权威信息发布的核心窗口，官网将全方位呈现企业发展面貌。',
    body = '<p>近日，安徽宁商科技集团官方网站正式开通运行。作为集团对外品牌展示与权威信息发布的核心窗口，官网将全方位呈现企业发展面貌，为客户、合作伙伴及社会各界搭起便捷的线上沟通渠道。</p><p>据了解，安徽宁商科技集团扎根合肥市包河区，依托合肥科创名城的产业资源优势，布局数字科技、智能装备、法务科技、工程配套、企业综合服务五大核心赛道，打造"技术+装备+服务+风控"全周期政企综合解决方案体系。此次官网上线，是集团数字化品牌建设的重要一步，也是其"城湖共生、笃行致远"发展理念的落地体现。</p><p>新上线的官网沿用集团统一品牌视觉规范，设置集团概况、新闻中心、产业布局、企业文化、联系我们等核心栏目，内容覆盖企业发展历程、组织架构、业务详情、动态资讯、招聘信息等多个维度。后续平台将持续更新集团重点动态、项目落地成果、行业相关资讯等内容，打造信息透明、访问便捷的官方线上主阵地。</p><p>下一步，安徽宁商科技集团将以此次官网上线为新起点，持续打磨数字化服务能力，优化品牌传播矩阵，以更专业的形象、更高效的服务对接市场需求，深耕安徽本土市场，稳步拓展业务布局，与各界合作伙伴携手开拓产业发展新局。</p>'
WHERE id = 2;

INSERT INTO news (title, category, category_name, date, author, source, summary, body, news_id)
VALUES ('习近平总书记三次考察安徽的科技创新部署', 'industry', '产业动态', '2026-08', '新华社', '新华社', '考察脉络与核心要求：党的十八大以来习近平总书记三次赴安徽考察均聚焦科技创新，2016年考察中国科技大学及先进技术研究院，提出“把创新作为最大政策，奋起直追、迎头赶上”；2020年参观安徽创新馆，明确“实现跨越式发展，关键靠创新”；2024年10月考察合肥滨湖科学城，强调“推进中国式现代化，科学技术要打头阵，科技创新是必由之路”，要求始终锚定高水平科技自立自强目标。', '<p>考察脉络与核心要求：党的十八大以来习近平总书记三次赴安徽考察均聚焦科技创新，2016年考察中国科技大学及先进技术研究院，提出“把创新作为最大政策，奋起直追、迎头赶上”；2020年参观安徽创新馆，明确“实现跨越式发展，关键靠创新”；2024年10月考察合肥滨湖科学城，强调“推进中国式现代化，科学技术要打头阵，科技创新是必由之路”，要求始终锚定高水平科技自立自强目标。</p><p>原始创新能力提升要求：三次考察均重点关注基础研究与科技成果突破，总书记先后指出科技创新依赖国外不可持续、要集中力量办好自己的事，强调高新技术讨不来、要不来，要求加强关键共性技术、前沿引领技术、现代工程技术、颠覆性技术创新，扩大国际科技交流合作，从源头和底层解决关键核心技术问题，应对国际科技竞争。</p><p>科技成果转化与新质生产力发展方向：总书记明确提高科技成果转化水平是对接科技创新与产业创新、形成新质生产力的关键，要求守好实体经济根基，加快传统产业改造升级，壮大战略性新兴产业，超前布局未来产业，因地制宜发展新质生产力，建设具有国际竞争力的先进制造业集群，为经济稳增长、促转型提供支撑。</p><p>教育科技人才一体改革部署：总书记肯定合肥的人才培育优势，指出科研工作者是推进中国式现代化的骨干，要求统筹推进教育科技人才体制机制一体改革，推动创新链、产业链、资金链、人才链深度融合，向改革要动力、以人才增活力，最大限度激发人才创新创造活力。</p><p>来源：新华社</p>', 'industry-xjp-anhui-science');

INSERT INTO news (title, category, category_name, date, author, source, summary, body, news_id)
VALUES ('以人工智能牵引新应用——我国人工智能产业发展透视', 'industry', '产业动态', '2026-07', '新华社记者魏玉坤、周圆、何晓', '新华社', '新华社记者魏玉坤、周圆、何晓', '<p>新华社记者魏玉坤、周圆、何晓</p><p>2026世界人工智能大会暨人工智能全球治理高级别会议将于7月17日至20日在上海举行，各方将进一步加强国际人工智能合作。记者日前在调研中了解到，以人工智能牵引新应用，用新场景打造新业态，人工智能这个“关键变量”，正在成为产业转型升级的“强劲增量”。</p><p>用新场景打造新业态</p><p>盛夏时节，记者走进特变电工沈阳变压器集团有限公司看到，两座“工厂”同步运转：一座是实体工厂，机械臂精准作业、AGV智能运输车往来穿梭，工人与智能装备有序合作；另一座是“虚拟工厂”，仿真验证系统快速校验排产排程方案合理性，有效减少实物试制次数。</p><p>公司流程与数字化管理部部长许林林说，这套覆盖“仿真—排产—执行—监控”全链条的智能体系，让产品研制周期缩短21%，生产效率提升40%。</p><p>人工智能是新一轮科技革命和产业变革的重要驱动力量。2025年，我国人工智能核心产业规模超过1.2万亿元，企业数量超过6200家。</p><p>在共享出行领域，AI大模型成为共享出行平台的“中枢大脑”，显著解决传统模式下车辆空驶率高、调度低效的痛点。</p><p>“我们自主研发人工智能运营管理系统，能够综合分析特定区域的地形地貌、人口分布、历史骑行数据等多维信息，实现对电单车投放、动态调度、电池管理、故障预警及动态定价的全流程精细化智能管控，持续优化共享出行体验。”松果出行创始人兼董事长翟光龙说。</p><p>随着全球能源转型步伐不断加快，全面推广露天矿无人驾驶成为智慧矿山建设的重要内容。聚焦露天矿无人驾驶技术研发与产业化落地，一些民营企业创新领跑。</p><p>“公司持续突破感知、决策、集群调度等关键技术，升级露天矿无人驾驶解决方案，实现在极寒、高温、高海拔等极端工况下规模化商业应用。截至6月，该方案已在40余座矿山落地，赋能超3100台无人驾驶矿卡常态化运行，规模全球领先。”易控智驾有关负责人说。</p><p>数据显示，我国超过30%的规模以上制造业企业实现人工智能技术覆盖，人工智能渗透领航级智能工厂70%以上的业务场景，沉淀超过6000个垂直领域模型。</p><p>智能体持续引爆市场</p><p>在创新引领和需求释放的双重作用下，我国以人形机器人为代表的具身智能产业规模，正在以超50%的增速跨越式发展。</p><p>伴着动感节拍，人形机器人灵活起舞，接连完成后空翻等高难度动作；切换工作模式后，巡检机器人化身安保开启巡逻，精准识别未登记人员……在智元创新（上海）科技股份有限公司展厅，具身智能机器人丰富的应用场景让人印象深刻。</p><p>今年6月28日，智元第15000台具身智能机器人下线，刷新全球行业量产纪录。第15000台精灵G2机型，下线即交付龙旗科技工厂投入常态化产线作业。</p><p>“龙虾”等智能体持续引爆市场、Seedance 2.0视频生成模型以“电影级”效果风靡全球……我国大模型、智能体等加速迭代，5月底日均词元调用量已达数百万亿、全球领先，今年人形机器人全年整机产量有望突破10万台。</p><p>科技创新与产业升级同频共振，也在不断催生新产品新服务，激活新的消费需求。今年前5个月，包括智能眼镜在内的可穿戴智能设备零售额同比增长超过一倍，限额以上单位仓储会员店、无人值守商店零售额增速均超过20%。</p><p>“人工智能+”激活全域创新活力</p><p>发展成果惠及全体人民，是技术迭代的应有之义。推动人工智能健康有序发展，要持续增进民生福祉，让更多创新成果“飞入寻常百姓家”。</p><p>实体黑板与电子屏幕自然融合，老师刚在黑板上写下函数公式，书写内容便被数字化，电子屏幕上随即呈现对应的动态图像，抽象的数学概念变得直观生动……这是科大讯飞全新升级的讯飞同窗AI黑板，旨在丰富教学内容，提升教学效率。</p><p>今年以来，科大讯飞持续推动人工智能与教育深度融合，支持教育数字化转型，目前已经为全国5万余所学校、1.3亿师生提供智慧教育产品和解决方案。</p><p>北京北儿窦店儿童医院引入AI儿科医生、深圳市养老护理院引入多种不同类型的养老机器人、杭州西湖景区创新引入机器人集群参与夜间执勤……从医疗到养老，再到社会治理，人工智能与百姓生活深度融合，更好满足人民对美好生活的向往。</p><p>《关于深入实施“人工智能+”行动的意见》等新政策相继出台，“十五五”规划纲要部署全面实施“人工智能+”行动，一系列顶层设计推动人工智能持续激活全域创新活力。</p><p>重庆鼓励重点商业场所开展智慧化改造，广东建设智能网联汽车测试区和车路协同设施，海南打造国际旅游消费智能体验岛……各地因地制宜营造良好创新生态，抢占人工智能产业应用制高点。</p><p>“紧抓新一轮科技革命和产业变革机遇，促进人工智能技术创新与应用发展双向赋能，将充分发挥我国产业体系完备、应用场景广阔等优势，为经济高质量发展注入新动能，推动全体人民共享人工智能发展红利。”商务部研究院研究员庞超然说。</p><p>来源：新华网</p>', 'industry-ai-new-apps');

INSERT INTO news (title, category, category_name, date, author, source, summary, body, news_id)
VALUES ('合肥“十五五”科创与产业发展规划', 'industry', '产业动态', '2026-08', '合肥市人民政府', '合肥市人民政府', '科创基础与总体目标：作为全国第二个综合性国家科学中心城市，合肥“十四五”期间科创实力大幅跃升，全球科技集群排名升至第39位，五年跃升40位，位居全球科研城市第12位、国家创新型城市前10位；建成、在建及预研大科学装置共13个，集聚度全国领先，量子信息、聚变能源、深空探测三大科创高地建设成效显著。“十五五”期间将以“科技创新策源地建设塑造新优势”“新兴产业聚集地建设实现新突破”为核心目标，力争到20', '<p>科创基础与总体目标：作为全国第二个综合性国家科学中心城市，合肥“十四五”期间科创实力大幅跃升，全球科技集群排名升至第39位，五年跃升40位，位居全球科研城市第12位、国家创新型城市前10位；建成、在建及预研大科学装置共13个，集聚度全国领先，量子信息、聚变能源、深空探测三大科创高地建设成效显著。“十五五”期间将以“科技创新策源地建设塑造新优势”“新兴产业聚集地建设实现新突破”为核心目标，力争到2030年基本建成具有国际影响力的科技创新中心，全市经济总量迈上2万亿元台阶，战新产业产值占规上工业比重达63％。</p><p>科创领域重点任务：未来五年合肥将以滨湖科学城实体化改革为牵引，打造世界一流大科学装置集群，实现高能级科创平台体系化布局，重点在量子信息、聚变能源、深空探测等领域产出原创性、颠覆性成果，在集成电路、人工智能、网络信息安全等领域攻克一批关键核心技术，同时依托上海（长三角）国际科技创新中心建设，提升全球创新影响力。</p><p>产业体系建设规划：“十五五”期间合肥将构建“654X”产业体系，其中6大主导产业包括智能网联新能源汽车、新一代信息技术、新能源、新材料、智能家电（居）、高端装备制造；5大新兴产业聚焦人工智能、低空经济、商业航天、安全应急、生物医药和高端医疗器械；4大未来产业瞄准量子科技、核聚变能和氢能、生物制造、具身智能，同时前瞻布局脑机接口、第六代移动通信、深空深海等新赛道。</p><p>重点产业发展进展：合肥新能源汽车已形成全链条布局，是全国唯一集齐换电、双智、产业链供应链体系、车路云一体化、车网互动五大试点的城市，2025年产量达137.1万辆，占全国总产量的8.3％，位居全国城市首位。“十五五”开局之年将重点提升车规级芯片、智能底盘、汽车电子等核心配套能力，推动全链条一体化升级。同时将推动现代生产性服务业提质升级，发展软件信息、科技服务等重点产业，培育研发设计、工业设计等业态，争创国家新型工业化示范区。</p><p>来源：合肥市人民政府</p>', 'industry-hefei-15th-plan');

INSERT INTO news (title, category, category_name, date, author, source, summary, body, news_id)
VALUES ('2026国家智能建造政策全文解读住建部新规要点与实施路径', 'trend', '行业资讯', '2026-01', '住建部', '住建部', '一、政策顶层设计：明确智能建造战略定位', '<p>一、政策顶层设计：明确智能建造战略定位</p><p>2026年是“十五五”规划开局之年，也是智能建造全面推广元年。2025年12月住建部联合13部门印发《关于全面推进智能建造发展的指导意见》，搭建国家、省、市三级联动政策体系，把智能建造纳入新质生产力，作为建筑业高质量发展核心引擎。</p><p>2026年政府工作报告、《“十五五”规划纲要》均重点部署数智化与智能建造，划定五年发展路线。</p><p>发展目标</p><p>1.2030年：大中型项目智能建造适用技术应用占比70%，培育100家行业骨干企业；</p><p>2.2035年：建成智能建造强省，形成完整全产业链协同生态。资金配套：2026年全国智能建造专项财政扶持资金超300亿元，覆盖技术研发、示范工程、人才培养三大领域。</p><p>二、住建部三大硬性新规，重塑行业准入规则</p><p>（一）BIM正向设计成为强制门槛</p><p>全国24个智能建造试点城市（北上广深、雄安、成都等）所有新建政府投资项目，必须全程采用BIM正向设计，杜绝先CAD绘图再翻模应付检查的模式，要求方案阶段即以三维建模为核心，打通设计、施工、运维全流程数字数据。行业现状：2026年初大型房建、基建项目BIM深度应用率78.3%，较2024年提升22.6个百分点；应用BIM可减少30%以上设计图纸变更。费用保障：住建部新规将BIM等数字化服务费划入工程建设其他费用，由建设单位承担。地方同步加码，例如青海要求1万㎡以上公建、2万㎡以上地产项目全过程使用BIM。</p><p>（二）AI审图、智慧工地是开工必备前置条件</p><p>AI审图全面普及：全国施工图审查系统统一接入AI审查模块，自动排查结构隐患、规范冲突，人工复核比例上限20%；AI可批量比对数百条规范，设计方案优化效率提升30%以上。</p><p>智慧工地一票否决制：项目开工前必须搭建完整监管平台，配齐人员实名制、视频监控、环境监测、危大工程预警系统，未达标不予发放施工许可证。施工现场强制配套智能塔吊、测量机器人、无人机巡检设备，对起重机械、高危工序自动预警，强化施工安全管控。</p><p>（三）推动全产业链数字化协同融合</p><p>政策要求智能建造联动装配式建筑、绿色建造，扶持国产建筑工业软件与工程感知控制系统研发。</p><p>城市更新领域重点发力：2026年城市更新专项债额度同比上涨15%，依托智能建造改造老旧小区、地下管网，提升存量建筑改造质量与效率。</p><p>同步推进“好房子”体系建设，将数字化技术贯穿住宅设计、施工、运维全周期，推广标准化绿色建材，实现住宅产品规范化发展。</p><p>三、分层落地实施路径：企业、项目、监管端实操要求</p><p>1.企业转型实施方向</p><p>建筑企业需搭建三大核心能力：搭建BIM+CIM一体化数据平台，打通项目全生命周期信息；批量引入建筑机器人、自动化施工装备；组建专属智能建造研发应用人才团队。</p><p>企业可申报示范项目、申领300亿财政补贴，享受研发、人才培养相关政策倾斜。</p><p>2.项目全流程落地规范</p><p>前期：方案阶段启动BIM正向建模；开工前完成整套智慧工地软硬件部署，保障监控、预警、实名制功能全覆盖。</p><p>施工阶段：常态化使用无人机、智能塔吊、测量机器人，依靠AI优化施工工序；</p><p>运维阶段：依托数字模型实现设备在线监测、能耗调控、突发情况智能应急，提升建筑长期管理水平。</p><p>3.行业监管配套机制</p><p>住建部持续完善BIM应用、AI审图、智慧工地统一技术标准；建立常态化考核制度，将智能建造落地成效纳入项目评优、建筑企业资质审核，倒逼政策落地执行。</p><p>四、政策带来的行业变革与发展机遇</p><p>全面落地的智能建造政策，将推动建筑业摆脱传统粗放模式，转向数字化、智能化、绿色化高质量发展，释放三重红利：</p><p>上下游产业扩容：BIM软件、AI审图系统、建筑智能装备市场需求持续上涨；</p><p>企业竞争格局重构：具备数字化施工能力的企业更容易承接项目、扩大市场份额；</p><p>完整产业生态成型：智能、装配、绿色建造深度融合，全产业链协同创新加速。发展启示：建筑企业需主动布局数字技术提升竞争力；从业人员学习BIM、AI工地等数字化技术，是未来职业晋升核心优势。长期来看，行业将完成转型升级，打造升级版“中国建造”。</p><p>来源：莱佳德科技</p>', 'trend-smart-construction-2026');

INSERT INTO news (title, category, category_name, date, author, source, summary, body, news_id)
VALUES ('2026年中国智能制造装备行业现状及趋势分析，国产替代提速，产业链自主可控', 'trend', '行业资讯', '2026-01', '华经产业研究院', '华经产业研究院', '一、智能制造装备产业概述', '<p>一、智能制造装备产业概述</p><p>智能制造装备是具备感知、分析、推理、决策、控制能力的高端制造装备总称，是先进制造、信息与智能技术深度融合的产物。它依托传感器、工业软件、物联网与AI实现自主运行、自适应调节与全生命周期优化，可显著提升加工精度、生产效率与柔性制造水平，是智能制造的核心载体，也是衡量制造业现代化水平的关键标志。</p><p>二、智能制造装备行业发展相关政策</p><p>我国以《中国制造2025》为总纲，构建“规划—工程—标准—专项”全链条政策体系，将智能制造装备列为制造强国核心抓手。从技术攻关、首台套补贴、产业基金、标准建设到AI融合，持续强化顶层设计与资金倾斜，推动装备从单机自动化向数字化、网络化、智能化升级，显著提升国产化率与全球竞争力。</p><p>相关报告：华经产业研究院发布的《2026-2032年中国智能制造装备行业市场深度研究及投资风险评估报告》</p><p>三、智能制造装备行业产业链</p><p>1、智能制造装备行业产业链结构图</p><p>智能制造装备产业链上游核心零部件与工业软件技术壁垒高、利润集中，国产化加速推进；中游装备规模扩张；下游汽车、电子、新能源需求旺盛，推动全链协同发展。政策与技术双轮驱动下，产业链正突破“卡脖子”环节，向自主可控、软硬融合、全链路智能化演进，成为制造强国建设核心支撑。</p><p>2、智能制造装备行业上游分析</p><p>2024年我国伺服电机市场规模约223亿元，销量同步大幅提升，成为智能制造装备核心零部件中增长最快的品类之一。伺服电机作为工业机器人、数控机床、智能产线的关键执行部件，其市场扩容直接支撑装备精度与柔性升级，加速国产替代进程，有效降低整机成本，提升智能制造装备性价比与市场渗透率。</p><p>四、智能制造装备行业现状分析</p><p>2025年中国智能制造装备行业市场规模约为4.79万亿元，连续多年领跑全球制造装备市场。下游新能源、汽车、电子等领域智能化改造需求旺盛，带动工业机器人、智能机床、自动化产线等核心装备快速放量，本土企业国产化率稳步提升，成为支撑制造业高质量发展的核心支柱。</p><p>五、智能制造装备行业竞争格局</p><p>当前国内智能制造装备竞争中，长三角、珠三角、环渤海三大集群集聚全国大部分头部企业，汇川、埃斯顿、新松等在伺服、机器人、数控系统等核心环节加速国产替代。外资在高端市场仍占优势，但本土龙头逐步缩小差距。行业集中度提升，正从“设备竞争”转向生态与解决方案竞争，向高端化、自主可控、服务化升级。</p><p>六、智能制造装备行业未来发展趋势</p><p>在政策与市场双重驱动下，智能制造装备上游核心零部件国产化进入深水区，产业链自主可控水平持续提高。截至2025年，谐波减速器国产化率达58.3%，，伺服电机、传感器等关键部件自给率稳步攀升。汇川技术、埃斯顿、华中数控等本土龙头加大研发投入，在伺服系统、机器人控制器、五轴数控系统等领域突破技术壁垒。高端市场中，国产装备在新能源、光伏、3C电子等领域逐步替代外资产品，2025年本土品牌工业机器人国内份额变大。核心部件自主化降低整机部分成本，提升装备性价比，推动行业从规模扩张向技术引领、自主可控转型。</p><p>华经产业研究院通过对中国智能制造装备行业海量数据的搜集、整理、加工，全面剖析行业总体市场容量、竞争格局、市场供需现状及行业典型企业的产销运营分析，并根据行业发展轨迹及影响因素，对行业未来的发展趋势进行预测。帮助企业了解行业当前发展动向，把握市场机会，做出正确投资决策。更多详细内容，请关注华经产业研究院出版的《2026-2032年中国智能制造装备行业市场深度研究及投资风险评估报告》。</p><p>来源：华经情报网</p>', 'trend-smart-manufacturing-2026');

INSERT INTO news (title, category, category_name, date, author, source, summary, body, news_id)
VALUES ('重磅！2026年中国及31省市电子竞技行业政策汇总及解读', 'trend', '行业资讯', '2026-03', '前瞻产业研究院', '前瞻产业研究院', '以下数据及分析来自于前瞻产业研究院电子竞技研究小组发布的《中国电子竞技行业市场前景预测与投资战略规划分析报告》', '<p>以下数据及分析来自于前瞻产业研究院电子竞技研究小组发布的《中国电子竞技行业市场前景预测与投资战略规划分析报告》</p><p>行业主要上市公司：腾讯控股（00700.HK）；网易（NTES.NASDAQ）；巨人网络（002558）；完美世界（002624）等</p><p>本文核心数据：电子竞技相关政策</p><p>全文统计口径说明：资料来源于各省份官网</p><p>1、政策历程图</p><p>从政策发展来看，我国电竞行业相关政策发展经历了大致五个阶段，即萌芽阶段、遭受打击、重新开始、缓慢发展和蓬勃发展，目前我国电竞行业相关政策正处于蓬勃发展阶段。</p><p>2、国家层面政策汇总及解读</p><p>——国家层面电子竞技行业政策汇总</p><p>我国电竞行业起步阶段受到行业政策、文化因素等各方面因素制约，一直到2003年11月，国家体育总局将电子竞技运动设立为正式开展的第99个体育项目，电竞行业才逐渐受到正视和关注。随着LOL、DOTA等产品走红，电竞开始以正面形象出现在大众媒体。十三五、十四五及十五五相关规划推动产业持续发展。多面政策利好下，网络巨头企业也纷纷展开电竞布局，电竞行业迎来全面爆发。</p><p>注：统计时间截至2026年3月5日，下同。</p><p>——国家层面电子竞技行业发展目标解读</p><p>2024年7月，国务院发布《关于促进服务消费高质量发展的意见》，提出加快构建新发展格局，统筹扩大内需和深化供给侧结构性改革，扩大服务业开放，着力提升服务品质、丰富消费场景、优化消费环境，以创新激发服务消费内生动能，培育服务消费新增长点，《意见》提出了提升网络游戏质量，支持电子竞技发展等目标。</p><p>3、各省市层面的政策汇总及解读</p><p>——重点省市电子竞技行业政策汇总</p><p>四大一线城市为全国电子竞技行业发展的前列城市，全国绝大多数大型赛事、俱乐部、电子竞技公司均分布在这些城市。除了发展早所带来的先发优势，区位因素和经济发展水平也是一线城市在电子竞技行业占据重要地位的原因。而其他地区为了快速发展电子竞技行业，自然也会结合本地特色推出相似甚至更优惠的政策。</p><p>——31省市电子竞技行业发展目标或方向解读</p><p>根据各地电竞行业相关政策规划来看，政策大体可以分为三类：补贴型、规划发展型、推动型，其中北京、上海、广东相关政策较多，支持力度较大。具体地区电子竞技行业政策目标规划如下：</p><p>更多本行业研究分析详见前瞻产业研究院《中国电子竞技行业市场前景预测与投资战略规划分析报告》。</p><p>同时前瞻产业研究院还提供产业大数据、产业研究报告、产业规划、园区规划、产业招商、产业图谱、智慧招商系统、行业地位证明、IPO咨询/募投可研、IPO工作底稿咨询等解决方案。在招股说明书、公司年度报告等任何公开信息披露中引用本篇文章内容，需要获取前瞻产业研究院的正规授权。</p><p>来源：前瞻产业研究院</p>', 'trend-esports-policy-2026');

INSERT INTO news (title, category, category_name, date, author, source, summary, body, news_id)
VALUES ('长鑫科技上市及合肥国资投资收益情况', 'trend', '行业资讯', '2026-07', '', '', '长鑫科技上市表现：2026年7月27日长鑫科技登陆上交所科创板，盘中最高涨幅超530％，最终收涨465.8％，报49元／股，总市值达3.28万亿，成为A股市值榜首，也是首只单日成交额破千亿元的个股。2026年一季度长鑫科技营收508亿元，同比增长719.1％，公司预计2026年上半年营收1100亿至1200亿元，归母净利润500亿至570亿元，有海外机构给出最高7.8万亿的市值目标。', '<p>长鑫科技上市表现：2026年7月27日长鑫科技登陆上交所科创板，盘中最高涨幅超530％，最终收涨465.8％，报49元／股，总市值达3.28万亿，成为A股市值榜首，也是首只单日成交额破千亿元的个股。2026年一季度长鑫科技营收508亿元，同比增长719.1％，公司预计2026年上半年营收1100亿至1200亿元，归母净利润500亿至570亿元，有海外机构给出最高7.8万亿的市值目标。</p><p>合肥国资持股及收益：安徽、合肥国资通过清辉集电、长鑫集成、安徽省投等多个平台持有长鑫科技约四成股份，其中清辉集电、长鑫集成实控人均为合肥市国资委及经济技术开发区国资体系，长鑫集成由合肥市国资委通过合肥产投100％控股。按2026年7月27日收盘价估算，安徽、合肥国资持有的长鑫科技股份市值超1.3万亿元。</p><p>合肥国资对长鑫科技的扶持历程：2016年合肥国资与兆易创新合作成立长鑫存储，面对DRAM技术门槛高、投入大的局面，合肥产投在一期180亿元项目预算中出资144亿元，占比80％；后续合肥国资多轮加码投资，同时带动阿里等产业资本、金融机构跟投，支撑长鑫科技渡过累计超三百亿元的亏损阶段，最终攻克DRAM核心工艺和产能良率难题，实现全产业链自主可控。</p><p>合肥产业投资过往成果</p><p>投资京东方：2008年全球金融危机冲击面板行业，京东方合肥6代线175亿元投资计划面临压力，合肥为突破海外液晶面板垄断、支撑本地家电产业发展，拿出全市三分之一的财政共计90亿元推动项目落地。项目投产后建成国内首条高世代液晶面板生产线，产出大陆首台32英寸液晶屏幕，成为京东方经营转折点，后续京东方8.5代线、10.5代线相继落地合肥，带动玻璃基板、偏光片、驱动芯片等上下游产业链企业集聚，合肥逐步发展为全球重要的新型显示产业基地。</p><p>投资蔚来：2020年蔚来面临现金流断裂风险，美股股价跌至1美元附近，合肥建投等机构向蔚来中国注资70亿元，换取24.1％的股份。蔚来借此渡过难关，抓住新能源汽车渗透率快速提升的行业机遇，合肥不仅在蔚来的股价上涨中获得十倍以上的账面回报，还推动蔚来中国总部落地合肥，为后续新能源汽车产业链企业集聚奠定基础。</p><p>其他投资成果：合肥还推动晶合集成落地，使其成为中国大陆第三家实现“A＋H”两地上市的晶圆代工企业；与维信诺合作建设总投资千亿元的多条柔性AMOLED生产线。截至视涯科技上市时，合肥共有上市公司96家，其中科创板上市公司21家；目前合肥产投投资的乐聚机器人、微容科技等多个项目正在冲刺创业板、科创板IPO，合肥创投投资的华宇电子、钜芯科技正在冲刺北交所。</p><p>合肥产业投资模式的核心特点</p><p>提前布局股权财政：在“土地财政”逐步趋弱的背景下，合肥早于2016年投资长鑫科技时便开始探索“股权财政”路径，通过国有资本领投优质硬科技项目，吸引社会资本参与，既推动本地产业集群建设，又通过股权增值获得财政收入，实现产业发展与财政增收的良性循环。</p><p>押注高赔率硬科技赛道：合肥偏好投资“公司发展不确定但行业趋势确定”的高赔率项目，敢于在企业发展的困境阶段大手笔投入：2008年拿出全市三分之一财政投资京东方，2016年长鑫一期项目出资占比达80％，2020年在蔚来濒临退市时注资70亿元。合肥高新创业投资管理合伙企业成立10年间累计投资400个项目，80％以上为偏早期首轮投资，整体实际早期科创项目布局占比达20％－30％。</p><p>投资思路清晰，机构分工明确：合肥锚定半导体、电子、新能源汽车三大核心赛道，辅以布局生物医药、商业航天，前瞻布局核聚变、量子科技等前沿赛道；旗下合肥建投、合肥产投、合肥高投、合肥兴泰控股等投资机构分工明确，可针对不同企业特点匹配差异化投资策略，大幅提升投资成功率。</p>', 'trend-cxram-listing');

INSERT INTO news (title, category, category_name, date, author, source, summary, body, news_id)
VALUES ('宁商科技集团召开7月份月度绩效工作总结会', 'staff', '员工风采', '2026-07', '宁商科技集团品牌策划部', '内部资料', '2026年7月30日下午，安徽宁商科技集团组织召开7月份月度绩效工作总结专项会议，全面复盘各项经营管理工作成效。', '<p>为全面复盘7月份各项经营管理工作成效，精准查摆工作短板与不足，压实各部门岗位职责，细化落实下月重点工作任务，持续提升集团规范化运营与精细化管理水平，2026年7月30日下午，安徽宁商科技集团组织召开7月份月度绩效工作总结专项会议。会议由顾婷婷主持，集团各部门核心骨干全员参会。</p><p>会上，各部门依次围绕月度绩效指标达成、重点工作落地、现存问题难点及后续工作计划进行全面汇报，系统梳理7月份工作成果，深入剖析工作推进过程中存在的进度滞后、流程不规范、协同效率不足等问题。会议结合集团整体发展战略，对各部门工作成果予以肯定，针对现存短板明确整改方向、压实整改责任，并对8月份绩效考核、专项工作推进、体系建设等重点任务进行统筹部署、细化安排。</p><p>深耕实干稳推进，月度各项工作落地见效。7月份，集团各部门紧扣年度经营目标，各司其职、协同联动，扎实推进人事管理、品牌建设、高新申报、财务管控、运营统筹等各项重点工作，圆满完成月度阶段性工作任务，为集团高质量发展筑牢基础。</p><p>人力资源中心聚焦集团组织架构优化与人才体系建设，有序开展会计、平面设计、党务、法务等关键岗位招聘工作，同步完成全员人事档案、员工花名册更新完善，持续夯实集团人事基础管理工作。</p><p>运营部充分发挥统筹督导职能，顺利完成全员月度绩效考核工作，全面收集汇总各部门8月份工作计划，常态化督导品牌策划部各项工作落地；同时系统梳理集团子公司纳入对接相关事宜，启动各岗位岗位职责修订筹备工作，助力集团管理制度标准化、规范化升级。</p><p>品牌策划部高效推进集团品牌视觉体系搭建工作，圆满完成企业宣传手册定稿、企业文化墙内容设计及外框采购筹备工作，顺利敲定集团总LOGO设计方案，4个子公司LOGO已完成初稿设计；稳步推进员工工牌定制工作，高效完成各类品牌辅助配套工作，持续统一集团品牌视觉形象。</p><p>高新申报部精准布局科技资质申报工作，聚焦科技型中小企业申报核心任务，顺利完成合作机构筛选、资质核验与最终确认工作，为后续申报材料编制、合同签订及项目申报工作有序推进筑牢前置基础。</p><p>财务部严守财务规范管理底线，持续跟进银行对公账户开立进度，常态化整理日常账务凭证，督促全员规范完成报销单据提交、发票索取等工作，提前做好账务处理筹备，待集团业务正式开展后全面启动全套账务核算工作，保障集团财务工作合规有序。</p><p>凝心聚力启新程，笃行实干赋能高质量发展。会议总结强调，月度绩效复盘是提质增效、查漏补缺的重要抓手。全体员工要以本次会议为契机，正视工作短板、压实工作责任，严格对照既定工作节点、绩效标准推进各项工作。各部门要强化跨部门协同联动，聚焦品牌体系建设、高新资质申报、组织架构优化、财务规范管理四大核心任务，严把工作质量、严守时间节点、严控考核标准，以精细化管理、高效化执行推动集团各项工作提质增效，全力保障月度、年度经营目标圆满达成，持续赋能集团规模化、规范化高质量发展。</p>', 'staff-july-performance-meeting');
